package sessions

import "sync"

type Store struct {
	mu    sync.RWMutex
	items map[string]string
}

func New() *Store { return &Store{items: map[string]string{}} }

func (s *Store) Put(k, v string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.items[k] = v
}

